followup_catalog.query:
select jsonb_build_object(
 'ingest_sources',(select jsonb_agg(to_jsonb(s)) from public.ingest_sources s),
 'investigation_policies',(select jsonb_agg(jsonb_build_object('table',tablename,'policy',policyname,'command',cmd,'roles',roles,'using',qual,'check',with_check)) from pg_policies where schemaname='evidence_pipeline' and tablename in ('investigations','investigation_memberships','investigation_evidence_review_events','investigation_observations')),
 'd4_d5_objects',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity_arguments',pg_get_function_identity_arguments(p.oid))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname not in ('pg_catalog','information_schema') and p.proname in ('publish_explanation','mark_source_change')),
 'rejection_audit',(select to_regclass('public.publication_rejection_audit')::text)
) as inventory;
